            targets = first_pos_list(observation.get(key))
            if targets:
                break
        if not targets:
            if w and h:
                center = (w // 2, h // 2)
                return step_toward(self_pos, center)
            return [0, 0]
        best = targets[0]
        best_d = md(self_pos, best)
        for t in targets[1:]:
            d = md(self_pos, t)
            if d < best_d:
                best_d = d
                best = t
        return step_toward(self_pos, best)

    resources = first_pos_list(observation.get("resources"))
    if resources:
        best = resources[0]
        best_d = md(self_pos, best)
        for r in resources[1:]:
            d = md(self_pos, r)
            if d < best_d:
                best_d = d
                best = r
        return step_toward(self_pos, best)

